python3 - <<'PY'
import json
raw=open('.claudinite/local/usage.GENERATED.json').read()
d=json.loads(raw)
print("total bytes:",len(raw))
def size(o): return len(json.dumps(o,separators=(',',':')))
for tier in ('hours','days','weeks'):
    print(f"{tier}: {size(d[tier])} bytes, {len(d[tier])} rows")
    sub={}
    for row in d[tier].values():
        for k,v in row.items():
            sub[k]=sub.get(k,0)+size(v)
    for k,v in sorted(sub.items(),key=lambda x:-x[1]):
        print(f"    {k:18} {v:7} bytes")
PY

