30	// functions at the foot of this file.
31	import {
32	  USAGE_FIELDS, USAGE_VERSION, CAPTURE_DAY_FIELDS, WEEK_FROM_DAY, QUEUE_OUTCOMES,
33	  COUNTER_GROUPS, BARE_MAPS, USAGE_CAPS, hourKey, encodeUsageFile, decodeUsageFile,
34	} from './usage-format.mjs';
35	
36	// --- entry classification -----------------------------------------------------
37	// Every shape below was verified against real captured transcripts on a
38	// conversation-logs branch, not inferred from the harness docs.
39	
40	// A genuine human turn. POSITIVE test, deliberately: the transcript stamps a
41	// typed-by-a-person turn with `origin: { kind: 'human' }`, and everything else a
42	// user-role entry can be — a tool result, an injected/meta turn, a subagent's
43	// sidechain traffic, a compaction summary, a slash-command expansion, and (the one
44	// that matters most here) a scheduled-task firing, which carries
45	// `origin: { kind: 'task-notification', subkind: 'scheduled-trigger' }` — simply
46	// lacks that stamp. Testing FOR the human marker rather than against a list of
47	// automated ones means a new automated entry shape is excluded the day it appears
48	// instead of silently inflating the denominator.
49	//
50	// The honest boundary: an older harness wrote no `origin` at all. Those turns count
51	// as non-human, so a repo's very old captures under-report userMessages rather than
52	// over-reporting them. This is the most fragile line in the fold, which is why it is
53	// one function with a fixture per shape it excludes.
54	export function isUserMessage(entry) {
55	  return entry?.type === 'user' && entry?.origin?.kind === 'human';
