280	
281	// The Now group's header sentence, DERIVED and never a tile: the PRs waiting now, plus
282	// the scheduled runs whose own declaration cannot land the PR they will open. It is the
283	// `automerge` field read against each task's cadence, not a guess about tomorrow — and
284	// a task with no cadence term is counted apart, because "a day" is a promise its
285	// declaration never made.
286	export function workloadLine(waitingPrs, rows, { schedule, now }) {
287	  const producers = rows.filter((r) => r.scheduled
288	    && (r.declaration?.automerge === 'nothing' || r.declaration?.automerge == null));
289	  const daily = producers.filter((r) => r.periodMs !== null && r.periodMs <= DAY);
290	  const rest = producers.filter((r) => r.periodMs !== null && r.periodMs > DAY);
291	  const movement = producers.filter((r) => r.periodMs === null);
292	  const parts = [`${waitingPrs} open PR${waitingPrs === 1 ? '' : 's'}`];
293	  parts.push(waitingPrs ? 'every one waits for a person' : 'nothing waits for a person');
294	  if (daily.length) parts.push(`+${daily.length} a day from ${daily.map((r) => r.task).slice(0, 2).join(', ')}${daily.length > 2 ? ` +${daily.length - 2}` : ''}`);
295	  if (rest.length) parts.push(`${rest.length} more on longer cadences`);
296	  if (movement.length) parts.push(`${movement.length} more on movement`);
297	  return parts.join(' · ');
298	}
299	
300	// --- the quiet tail -------------------------------------------------------------------
301	
302	// One ruled line, not a group: the plain issues on no edge, counted by what matters.
303	export function quietTail(issues, edges, now) {
304	  const onEdge = new Set(edges.flatMap((e) => [e.from, e.to]));
305	  const quiet = issues.filter((i) => !isQueueItem(i) && !onEdge.has(i.number));
306	  const has = (i, label) => labelNames(i).includes(label);
307	  const rotting = quiet.filter((i) => (now - (ms(i.updated_at) ?? now)) >= ROT_DAYS * DAY);
308	  return {
309	    total: quiet.length,
